async function main(ctx) {
  const input = ctx.input || {};

  // Validate required fields
  if (!input.prompt || typeof input.prompt !== 'string') {
    throw new Error('prompt is required and must be a string');
  }

  // Set defaults
  const size = input.size || '1024x1024';
  const quality = input.quality || 'standard';
  const style = input.style || 'vivid';

  // Validate enum values
  const validSizes = ['1024x1024', '1792x1024', '1024x1792'];
  const validQualities = ['standard', 'hd'];
  const validStyles = ['vivid', 'natural'];

  if (!validSizes.includes(size)) {
    throw new Error('size must be one of: ' + validSizes.join(', '));
  }

  if (!validQualities.includes(quality)) {
    throw new Error('quality must be one of: ' + validQualities.join(', '));
  }

  if (!validStyles.includes(style)) {
    throw new Error('style must be one of: ' + validStyles.join(', '));
  }

  // Build enhanced prompt with style guidance
  let enhancedPrompt = input.prompt;

  if (style === 'vivid') {
    enhancedPrompt = 'Create a vivid, hyper-realistic, dramatic image: ' + input.prompt;
  } else {
    enhancedPrompt = 'Create a natural, realistic image: ' + input.prompt;
  }

  if (quality === 'hd') {
    enhancedPrompt = enhancedPrompt + '. High detail, sharp focus, professional quality.';
  }

  // Parse size dimensions
  const dimensions = size.split('x');
  const width = parseInt(dimensions[0]);
  const height = parseInt(dimensions[1]);

  return {
    messages: [
      {
        role: 'user',
        content: enhancedPrompt
      }
    ],
    imageConfig: {
      size: size,
      width: width,
      height: height,
      quality: quality,
      n: 1
    },
    originalPrompt: input.prompt,
    requestedSize: size,
    requestedQuality: quality,
    requestedStyle: style
  };
}

async function main(ctx) {
  const llmResponse = ctx.input || {};
  const preparedData = ctx.lastOutputOf('prepare_prompt') || {};

  // Extract the response
  const choices = llmResponse.choices || [];
  if (!choices.length) {
    throw new Error('No response from image generation model');
  }

  const message = choices[0].message || {};
  const content = message.content || '';

  // The model response should contain image data or URL
  // For now, we'll extract what we can from the response
  return {
    llmResponse: llmResponse,
    content: content,
    model: llmResponse.model || 'google/gemini-2.0-flash-exp:free',
    usage: llmResponse.usage || {},
    originalPrompt: preparedData.originalPrompt,
    enhancedPrompt: (preparedData.messages || [])[0]?.content || '',
    requestedSize: preparedData.requestedSize,
    requestedQuality: preparedData.requestedQuality,
    requestedStyle: preparedData.requestedStyle
  };
}

async function main(ctx) {
  const extracted = ctx.input || {};

  return {
    success: true,
    image: {
      content: extracted.content,
      model: extracted.model
    },
    metadata: {
      model: extracted.model,
      size: extracted.requestedSize || '1024x1024',
      quality: extracted.requestedQuality || 'standard',
      style: extracted.requestedStyle || 'vivid',
      original_prompt: extracted.originalPrompt,
      enhanced_prompt: extracted.enhancedPrompt,
      usage: extracted.usage
    },
    wordpress_ready: {
      content: extracted.content,
      alt_text: extracted.originalPrompt,
      caption: extracted.originalPrompt,
      description: 'Generated by Gemini: ' + extracted.originalPrompt
    },
    raw_response: extracted.llmResponse
  };
}
